  `max_crawl_depth` int unsigned NOT NULL DEFAULT 0,
  `max_crawl_pages` int unsigned NOT NULL DEFAULT 0,
  `pages_count` int unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL,
  `updated_at` timestamp NULL,
  `metadata` json NULL,
  PRIMARY KEY (`id`),
  KEY `datasets_external_id_index` (`external_id`),
  CONSTRAINT `datasets_project_id_foreign` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE CASCADE
